'use client';

import { createField } from '@dawitlabs/pixelfield';
import { useEffect, useRef } from 'react';

export interface BubblesProps {
  className?: string;
  tint?: string;
  seed?: number;
  interactive?: boolean;
}

export function Bubbles({ className, tint, seed = 0, interactive = true }: BubblesProps) {
  const ref = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = ref.current;
    if (!canvas) return;
    const field = createField(canvas, {
      generator: 'cells',
      falloff: 'up',
      scale: 1,
      aspect: 1,
      warp: 1.1,
      contrast: 0.8,
      mode: 'billow',
      speed: 1.1,
      intensity: 1,
      flow: { x: 0, y: -6 },
      seed,
      tint,
      interactive,
    });
    return () => field.destroy();
  }, [tint, seed, interactive]);

  return <canvas ref={ref} className={className} aria-hidden="true" />;
}

import { createField } from '@dawitlabs/pixelfield';

export function mountBubbles(canvas, { tint, seed = 0, interactive = true } = {}) {
  return createField(canvas, {
      generator: 'cells',
      falloff: 'up',
      scale: 1,
      aspect: 1,
      warp: 1.1,
      contrast: 0.8,
      mode: 'billow',
      speed: 1.1,
      intensity: 1,
      flow: { x: 0, y: -6 },
    seed,
    tint,
    interactive,
  });
}
